export const SECURITY_HTML = "<!-- ════════════════════════\r\n     HERO\r\n════════════════════════ -->\r\n<section class=\"hero\" aria-labelledby=\"hero-h\">\r\n  <div class=\"hero-orb hero-orb-1\" aria-hidden=\"true\"></div>\r\n  <div class=\"hero-orb hero-orb-2\" aria-hidden=\"true\"></div>\r\n  <div class=\"wrap\">\r\n    <div class=\"hero-inner\">\r\n      <nav class=\"hero-crumb rv\" aria-label=\"Breadcrumb\">\r\n        <a href=\"/\">Home</a><span class=\"hero-crumb-sep\" aria-hidden=\"true\">/</span>\r\n        <a href=\"/popia\">Trust</a><span class=\"hero-crumb-sep\" aria-hidden=\"true\">/</span>\r\n        <span aria-current=\"page\">Security</span>\r\n      </nav>\r\n      <div class=\"eyebrow rv d1\" style=\"margin-bottom:16px\">\r\n        <i style=\"background:var(--green)\"></i>\r\n        Trust centre · POPIA-native · Honest status on every control\r\n      </div>\r\n      <h1 class=\"hero-h rv d2\" id=\"hero-h\">\r\n        Security <span class=\"g\">built into</span><br>the architecture.\r\n      </h1>\r\n      <p class=\"hero-lead rv d3\">\r\n        Defence in depth from edge to embedding — how the AI Dev Platform is designed to protect your data. TLS in transit, AES-256 at rest, tenant isolation in the database, PII scrubbed before content reaches a model, and append-only audit logs. Every control below says whether it is in place today, in build, or designed.\r\n      </p>\r\n      <div class=\"hero-ctas rv d4\">\r\n        <a href=\"#documentation\" class=\"btn btn-p\">\r\n          Request documentation\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\r\n        </a>\r\n        <a href=\"mailto:tumiso@sonofgraig.com?subject=Security%20report\" class=\"btn btn-s\">\r\n          Report a vulnerability\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\r\n        </a>\r\n      </div>\r\n      <div class=\"hero-trust rv d5\">\r\n        <div class=\"ht-i\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Information Officer registered</div>\r\n        <div class=\"ht-i\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>South African region by design</div>\r\n        <div class=\"ht-i\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>MFA on every admin account</div>\r\n        <div class=\"ht-i\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>No certificates we don&rsquo;t hold</div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- ════════════════════════\r\n     STATUS STRIP\r\n════════════════════════ -->\r\n<div class=\"status-strip\" aria-label=\"Live security posture\">\r\n  <div class=\"wrap\">\r\n    <div class=\"status-g\">\r\n      <div class=\"status-i\">\r\n        <div class=\"status-dot ok\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></div>\r\n        <div class=\"status-meta\">\r\n          <div class=\"status-label\">Platform status</div>\r\n          <div class=\"status-val\">In build · early access</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"status-i\">\r\n        <div class=\"status-dot ok\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z\"/></svg></div>\r\n        <div class=\"status-meta\">\r\n          <div class=\"status-label\">Data region</div>\r\n          <div class=\"status-val\">South Africa by default</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"status-i\">\r\n        <div class=\"status-dot ok\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg></div>\r\n        <div class=\"status-meta\">\r\n          <div class=\"status-label\">Encryption</div>\r\n          <div class=\"status-val\">TLS · AES-256 at rest</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"status-i\">\r\n        <div class=\"status-dot ok\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\r\n        <div class=\"status-meta\">\r\n          <div class=\"status-label\">Certifications</div>\r\n          <div class=\"status-val\">POPIA · none claimed beyond</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- ════════════════════════\r\n     TOC TAB STRIP\r\n════════════════════════ -->\r\n<div class=\"toc-strip\" role=\"navigation\" aria-label=\"Security sections\">\r\n  <div class=\"wrap\">\r\n    <div class=\"toc-inner\">\r\n      <a class=\"toc-tab active\" data-target=\"pillars\" href=\"#pillars\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>Pillars</a>\r\n      <a class=\"toc-tab\" data-target=\"architecture\" href=\"#architecture\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/></svg>Architecture</a>\r\n      <a class=\"toc-tab\" data-target=\"compliance\" href=\"#compliance\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M9 12l2 2 4-4\"/><path d=\"M21 12c0 4.97-4.03 9-9 9s-9-4.03-9-9 4.03-9 9-9 9 4.03 9 9z\"/></svg>Compliance</a>\r\n      <a class=\"toc-tab\" data-target=\"controls\" href=\"#controls\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4\"/></svg>Controls</a>\r\n      <a class=\"toc-tab\" data-target=\"incident\" href=\"#incident\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/></svg>Incident response</a>\r\n      <a class=\"toc-tab\" data-target=\"responsibility\" href=\"#responsibility\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"8.5\" cy=\"7\" r=\"4\"/><path d=\"M20 8v6\"/><path d=\"M23 11h-6\"/></svg>Shared responsibility</a>\r\n      <a class=\"toc-tab\" data-target=\"subprocessors\" href=\"#subprocessors\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>Sub-processors</a>\r\n      <a class=\"toc-tab\" data-target=\"documentation\" href=\"#documentation\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>Documentation</a>\r\n      <a class=\"toc-tab\" data-target=\"faq\" href=\"#faq\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>FAQ</a>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- ════════════════════════\r\n     PILLARS — Defence in depth\r\n════════════════════════ -->\r\n<section class=\"section\" id=\"pillars\" aria-labelledby=\"pillars-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--blue)\"></i>01 · Defence in depth</div>\r\n      <h2 class=\"section-h\" id=\"pillars-h\">Six security pillars. <span class=\"g\">Every product. Every cluster.</span></h2>\r\n      <p class=\"section-lead\">Security is not a feature on the sonofgraig platform — it is the architecture itself. Each of the six pillars below is designed into the infrastructure or database layer, not left to application-level checks. That distinction matters: a misbehaving service cannot bypass a firewall, a residency rule, or a row-level security policy.</p>\r\n    </div>\r\n\r\n    <div class=\"pillar-g\">\r\n      <div class=\"pillar rv d1\">\r\n        <div class=\"pillar-num\">Pillar 01</div>\r\n        <div class=\"pillar-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.5\"><path d=\"M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z\"/></svg>\r\n        </div>\r\n        <div class=\"pillar-t\">Data residency</div>\r\n        <div class=\"pillar-d\">Customer data is stored in a South African cloud region by default. Residency is enforced in network and IAM policy — not just in a contract.</div>\r\n        <ul class=\"pillar-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>POPIA s72 transfers documented in your DPA</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Vector store inside the same region and network</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Egress allow-listed to approved endpoints</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"pillar rv d2\">\r\n        <div class=\"pillar-num\">Pillar 02</div>\r\n        <div class=\"pillar-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\r\n        </div>\r\n        <div class=\"pillar-t\">Encryption everywhere</div>\r\n        <div class=\"pillar-d\">TLS for everything moving. AES-256 for everything at rest, enforced at the storage layer. Secrets live in a managed vault — never in code or environment files.</div>\r\n        <ul class=\"pillar-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>TLS on every page of this site today</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>AES-256 at rest on database, vectors and files</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Managed secrets store, no keys in source</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Customer-managed keys planned for Enterprise</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"pillar green rv d3\">\r\n        <div class=\"pillar-num\">Pillar 03</div>\r\n        <div class=\"pillar-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.5\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\r\n        </div>\r\n        <div class=\"pillar-t\">Identity &amp; access</div>\r\n        <div class=\"pillar-d\">Role-based access at the application layer. Row-level security at the database layer. Least privilege for every internal service component.</div>\r\n        <ul class=\"pillar-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Row-level security scopes every tenant query</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>MFA on every admin and production account</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Short-lived JWTs with token rotation</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>SSO/SAML planned for Enterprise</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"pillar amber rv d1\">\r\n        <div class=\"pillar-num\">Pillar 04</div>\r\n        <div class=\"pillar-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.5\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\r\n        </div>\r\n        <div class=\"pillar-t\">PII protection in AI</div>\r\n        <div class=\"pillar-d\">South African PII is detected and redacted before any content reaches an embedding model, vector store or external model API. AI safety is a pipeline step, not a prompt instruction — try the demo below.</div>\r\n        <ul class=\"pillar-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Detects ID numbers, phones, emails, passports</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Runs synchronously before vectorisation</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Designed to be tested in CI on every deploy</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Only scrubbed payloads reach external models</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"pillar purple rv d2\">\r\n        <div class=\"pillar-num\">Pillar 05</div>\r\n        <div class=\"pillar-ico\" style=\"background:var(--purple-g);border:1px solid var(--purple-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--purple)\" stroke-width=\"1.5\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/></svg>\r\n        </div>\r\n        <div class=\"pillar-t\">Auditability</div>\r\n        <div class=\"pillar-d\">Every RAG query, every agent step and every administrative action is written to an append-only log. Hashes are stored — not raw content — so the audit log is a compliance record and not a secondary copy of personal information.</div>\r\n        <ul class=\"pillar-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>SHA-256 hashes of user IDs and queries</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Database rules reject log deletion</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Synchronous logging — no race conditions</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Records POPIA s.11 processing basis</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"pillar rv d3\">\r\n        <div class=\"pillar-num\">Pillar 06</div>\r\n        <div class=\"pillar-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>\r\n        </div>\r\n        <div class=\"pillar-t\">Edge &amp; network</div>\r\n        <div class=\"pillar-d\">Cloudflare sits in front of every public endpoint — including this site today — with WAF, bot protection, rate limiting and DDoS mitigation. Platform backends run in private networks with no public IPs.</div>\r\n        <ul class=\"pillar-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Cloudflare WAF with managed rule sets</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Per-IP and per-org rate limiting</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Private networks for all backends</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Single ingress, no direct database exposure</li>\r\n        </ul>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     ARCHITECTURE — Layered\r\n════════════════════════ -->\r\n<section class=\"section section-alt\" id=\"architecture\" aria-labelledby=\"arch-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--purple)\"></i>02 · Architecture</div>\r\n      <h2 class=\"section-h\" id=\"arch-h\">Five layers. <span class=\"g\">One designed posture.</span></h2>\r\n      <p class=\"section-lead\">From the edge that receives a request to the store that returns an embedding, every layer of the platform contributes a security control. Below, a single tenant request is traced from Cloudflare to the data layer and back — with the status of each layer today.</p>\r\n    </div>\r\n\r\n    <div class=\"arch-wrap\">\r\n      <div class=\"arch-stack\">\r\n\r\n        <div class=\"arch-layer rv d1\">\r\n          <div class=\"arch-layer-rail\" style=\"background:var(--blue)\"></div>\r\n          <div class=\"arch-layer-head\">\r\n            <div class=\"arch-layer-num\">L01</div>\r\n            <div class=\"arch-layer-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg></div>\r\n            <div>\r\n              <div class=\"arch-layer-title\">Edge — Cloudflare global network</div>\r\n            </div>\r\n            <span class=\"comp-status ok\">In place</span>\r\n          </div>\r\n          <div class=\"arch-layer-desc\">Every request hits Cloudflare first — this website already runs behind it. WAF rules block OWASP Top 10 patterns, bot protection stops automated scraping, and rate limits apply per IP and, on the platform, per organisation.</div>\r\n          <div class=\"arch-layer-tech\">\r\n            <span class=\"arch-tech-chip\">Cloudflare WAF</span>\r\n            <span class=\"arch-tech-chip\">DDoS L3/L4/L7</span>\r\n            <span class=\"arch-tech-chip\">Bot Management</span>\r\n            <span class=\"arch-tech-chip\">Rate limiting</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"arch-layer rv d2\">\r\n          <div class=\"arch-layer-rail\" style=\"background:var(--green)\"></div>\r\n          <div class=\"arch-layer-head\">\r\n            <div class=\"arch-layer-num\">L02</div>\r\n            <div class=\"arch-layer-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M2 12h20\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10\"/></svg></div>\r\n            <div>\r\n              <div class=\"arch-layer-title\">Ingress — TLS termination &amp; auth</div>\r\n            </div>\r\n            <span class=\"comp-status prog\">In build</span>\r\n          </div>\r\n          <div class=\"arch-layer-desc\">TLS is terminated at the load balancer in-region. Short-lived authentication tokens are validated. The organisation ID is extracted from the JWT claims and propagated through the request lifecycle for downstream RLS scoping.</div>\r\n          <div class=\"arch-layer-tech\">\r\n            <span class=\"arch-tech-chip\">TLS</span>\r\n                <span class=\"arch-tech-chip\">Load balancer</span>\r\n            <span class=\"arch-tech-chip\">JWT (short-lived)</span>\r\n            <span class=\"arch-tech-chip\">MFA enforced</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"arch-layer rv d3\">\r\n          <div class=\"arch-layer-rail\" style=\"background:var(--amber)\"></div>\r\n          <div class=\"arch-layer-head\">\r\n            <div class=\"arch-layer-num\">L03</div>\r\n            <div class=\"arch-layer-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.5\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg></div>\r\n            <div>\r\n              <div class=\"arch-layer-title\">Application — PII scrubbing &amp; AI gateway</div>\r\n            </div>\r\n            <span class=\"comp-status prog\">In build</span>\r\n          </div>\r\n          <div class=\"arch-layer-desc\">Document content passes through the PII scrubber before it ever reaches an embedding model. South-African personal identifiers are detected and redacted. The LiteLLM gateway sits between application services and any external LLM provider, so PII-scrubbed content is the only payload designed to leave our network.</div>\r\n          <div class=\"arch-layer-tech\">\r\n            <span class=\"arch-tech-chip\">PII Scrubber middleware</span>\r\n            <span class=\"arch-tech-chip\">LiteLLM gateway</span>\r\n            <span class=\"arch-tech-chip\">FastAPI</span>\r\n            <span class=\"arch-tech-chip\">tRPC</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"arch-layer rv d4\">\r\n          <div class=\"arch-layer-rail\" style=\"background:var(--purple)\"></div>\r\n          <div class=\"arch-layer-head\">\r\n            <div class=\"arch-layer-num\">L04</div>\r\n            <div class=\"arch-layer-ico\" style=\"background:var(--purple-g);border:1px solid var(--purple-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--purple)\" stroke-width=\"1.5\"><ellipse cx=\"12\" cy=\"5\" rx=\"9\" ry=\"3\"/><path d=\"M3 5v14a9 3 0 0 0 18 0V5\"/><path d=\"M3 12a9 3 0 0 0 18 0\"/></svg></div>\r\n            <div>\r\n              <div class=\"arch-layer-title\">Data — Multi-tenant isolation via RLS</div>\r\n            </div>\r\n            <span class=\"comp-status prog\">In build</span>\r\n          </div>\r\n          <div class=\"arch-layer-desc\">PostgreSQL row-level security policies scope every query to the authenticated organisation automatically. There is no application-layer filter to forget. Qdrant uses one named, independently encrypted collection per tenant. Cross-tenant access requires a database root credential, not an application bug.</div>\r\n          <div class=\"arch-layer-tech\">\r\n            <span class=\"arch-tech-chip\">PostgreSQL 16</span>\r\n            <span class=\"arch-tech-chip\">Row-level security</span>\r\n            <span class=\"arch-tech-chip\">Qdrant per-tenant</span>\r\n            <span class=\"arch-tech-chip\">AES-256 at rest</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"arch-layer rv d5\">\r\n          <div class=\"arch-layer-rail\" style=\"background:var(--blue-dim)\"></div>\r\n          <div class=\"arch-layer-head\">\r\n            <div class=\"arch-layer-num\">L05</div>\r\n            <div class=\"arch-layer-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><path d=\"M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z\"/></svg></div>\r\n            <div>\r\n              <div class=\"arch-layer-title\">Infrastructure — South African region</div>\r\n            </div>\r\n            <span class=\"comp-status plan\">Designed</span>\r\n          </div>\r\n          <div class=\"arch-layer-desc\">Platform workloads are designed to run in a South African cloud region, with no internet gateway by default and egress allow-listed to approved endpoints. Infrastructure is defined in Terraform, so every change is reviewable and auditable.</div>\r\n          <div class=\"arch-layer-tech\">\r\n            <span class=\"arch-tech-chip\">ZA cloud region</span>\r\n                <span class=\"arch-tech-chip\">Kubernetes</span>\r\n            <span class=\"arch-tech-chip\">Terraform IaC</span>\r\n            <span class=\"arch-tech-chip\">VPC private subnets</span>\r\n            <span class=\"arch-tech-chip\">Prometheus + Grafana</span>\r\n          </div>\r\n        </div>\r\n\r\n      </div>\r\n\r\n      <aside class=\"arch-right\">\r\n        <div class=\"arch-stat rv d1\" style=\"border-color:var(--green-b)\">\r\n          <div class=\"arch-stat-val\" style=\"color:var(--green)\">ZA</div>\r\n            <div class=\"arch-stat-label\">Customer data region by default — the model call is the one documented exception</div>\r\n        </div>\r\n        <div class=\"arch-stat rv d2\">\r\n          <div class=\"arch-stat-val\">Zero</div>\r\n          <div class=\"arch-stat-label\">Raw personal information designed to reach external model APIs</div>\r\n        </div>\r\n        <div class=\"arch-stat rv d3\">\r\n          <div class=\"arch-stat-val\">TLS</div>\r\n            <div class=\"arch-stat-label\">Every page of this site, today, via Cloudflare</div>\r\n        </div>\r\n        <div class=\"arch-stat rv d4\">\r\n          <div class=\"arch-stat-val\">AES-256</div>\r\n          <div class=\"arch-stat-label\">Platform data at rest, enforced at the storage layer</div>\r\n        </div>\r\n        <div class=\"arch-stat rv d5\" style=\"border-color:var(--amber-b)\">\r\n          <div class=\"arch-stat-val\" style=\"color:var(--amber)\">1 day</div>\r\n            <div class=\"arch-stat-label\">Response to vulnerability reports, every business day</div>\r\n        </div>\r\n      </aside>\r\n      </div>\r\n      <div data-mount=\"pii-demo\" class=\"rv\" style=\"margin-top:40px\"></div>\r\n    </div>\r\n  </section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     COMPLIANCE\r\n════════════════════════ -->\r\n<section class=\"section\" id=\"compliance\" aria-labelledby=\"comp-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--green)\"></i>03 · Compliance &amp; certifications</div>\r\n      <h2 class=\"section-h\" id=\"comp-h\">Compliance posture, <span class=\"g\">documented honestly.</span></h2>\r\n      <p class=\"section-lead\">We list every framework with its real status — active, in progress, or planned. We will never claim a certificate that has not been issued. The South African market deserves honest compliance reporting, and our enterprise procurement counterparties require it.</p>\r\n    </div>\r\n\r\n    <div class=\"comp-table rv\">\r\n      <div class=\"comp-row head\">\r\n        <div class=\"comp-cell head-c\">Framework</div>\r\n        <div class=\"comp-cell head-c\">What it covers</div>\r\n        <div class=\"comp-cell head-c\">Status</div>\r\n      </div>\r\n\r\n      <div class=\"comp-row\">\r\n        <div class=\"comp-cell\">\r\n          <div class=\"comp-cert-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.6\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\r\n          <div>\r\n            <div class=\"comp-cert-name\">POPIA</div>\r\n            <div class=\"comp-cert-sub\">Act 4 of 2013 · ZA</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"comp-cell\">South African Protection of Personal Information Act. Information Officer registered with the Information Regulator. The platform is designed around Section 11 (lawful processing), Section 19 (security safeguards), Section 22 (breach notification) and Section 72 (cross-border transfers).</div>\r\n        <div class=\"comp-cell\"><span class=\"comp-status ok\">Active</span></div>\r\n      </div>\r\n\r\n      <div class=\"comp-row\">\r\n        <div class=\"comp-cell\">\r\n          <div class=\"comp-cert-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.6\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg></div>\r\n          <div>\r\n            <div class=\"comp-cert-name\">SOC 2 Type II</div>\r\n            <div class=\"comp-cert-sub\">AICPA · Trust Services</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"comp-cell\">Third-party audit of security, availability and confidentiality controls. We do not hold a SOC 2 report and will not claim one until it is issued. If your procurement requires it today, we will tell you so plainly.</div>\r\n        <div class=\"comp-cell\"><span class=\"comp-status plan\">Not held</span></div>\r\n      </div>\r\n\r\n      <div class=\"comp-row\">\r\n        <div class=\"comp-cell\">\r\n          <div class=\"comp-cert-ico\" style=\"background:var(--purple-g);border:1px solid var(--purple-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--purple)\" stroke-width=\"1.6\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg></div>\r\n          <div>\r\n            <div class=\"comp-cert-name\">ISO/IEC 27001</div>\r\n            <div class=\"comp-cert-sub\">Information Security</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"comp-cell\">International information security management standard. Planned once the platform is generally available; not held today.</div>\r\n        <div class=\"comp-cell\"><span class=\"comp-status plan\">Planned</span></div>\r\n      </div>\r\n\r\n      <div class=\"comp-row\">\r\n        <div class=\"comp-cell\">\r\n          <div class=\"comp-cert-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.6\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"/><polyline points=\"2 17 12 22 22 17\"/><polyline points=\"2 12 12 17 22 12\"/></svg></div>\r\n          <div>\r\n            <div class=\"comp-cert-name\">EU AI Act readiness</div>\r\n            <div class=\"comp-cert-sub\">Regulation (EU) 2024/1689</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"comp-cell\">Risk classification and documentation of AI systems per the EU AI Act taxonomy. Required for customers serving EU data subjects or operating in EU jurisdictions. Risk classification and documentation will be produced for each platform AI system.</div>\r\n        <div class=\"comp-cell\"><span class=\"comp-status plan\">Planned</span></div>\r\n      </div>\r\n\r\n      <div class=\"comp-row\">\r\n        <div class=\"comp-cell\">\r\n          <div class=\"comp-cert-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.6\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg></div>\r\n          <div>\r\n            <div class=\"comp-cert-name\">GDPR alignment</div>\r\n            <div class=\"comp-cert-sub\">Regulation (EU) 2016/679</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"comp-cell\">DPA terms and privacy-by-design controls for customers with EU data subjects. POPIA controls cover most of the GDPR baseline.</div>\r\n        <div class=\"comp-cell\"><span class=\"comp-status prog\">Designed</span></div>\r\n      </div>\r\n\r\n      <div class=\"comp-row\">\r\n        <div class=\"comp-cell\">\r\n          <div class=\"comp-cert-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.6\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg></div>\r\n          <div>\r\n            <div class=\"comp-cert-name\">PAIA manual</div>\r\n            <div class=\"comp-cert-sub\">Promotion of Access to Information Act, ZA</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"comp-cell\">Promotion of Access to Information Act manual, published in draft at <a href=\"/paia\" style=\"color:var(--blue)\">sonofgraig.com/paia</a>. Covers categories of records held, the request procedure, and the Information Officer&rsquo;s contact details.</div>\r\n        <div class=\"comp-cell\"><span class=\"comp-status prog\">Draft</span></div>\r\n      </div>\r\n\r\n      <div class=\"comp-row\">\r\n        <div class=\"comp-cell\">\r\n          <div class=\"comp-cert-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.6\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\"/><line x1=\"8\" y1=\"21\" x2=\"16\" y2=\"21\"/></svg></div>\r\n          <div>\r\n            <div class=\"comp-cert-name\">B-BBEE certification</div>\r\n            <div class=\"comp-cert-sub\">B-BBEE Act, ZA</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"comp-cell\">Broad-Based Black Economic Empowerment certificate. Available to enterprise procurement teams on request — required for many South African enterprise and public-sector customers as part of supplier assessment.</div>\r\n        <div class=\"comp-cell\"><span class=\"comp-status ok\">On request</span></div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     CONTROL CARDS\r\n════════════════════════ -->\r\n<section class=\"section section-alt\" id=\"controls\" aria-labelledby=\"ctrl-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--amber)\"></i>04 · Security controls</div>\r\n      <h2 class=\"section-h\" id=\"ctrl-h\">The control catalogue. <span class=\"g\">With the status of each.</span></h2>\r\n      <p class=\"section-lead\">Security questionnaires move faster when answers are precise. The controls below are grouped by domain. Each one is marked: in place today, in build, or designed for the platform and not yet running.</p>\r\n    </div>\r\n\r\n    <div class=\"ctrl-g\">\r\n\r\n      <!-- 01 -->\r\n      <div class=\"ctrl rv d1\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">A — Cryptography</div>\r\n            <div class=\"ctrl-t\">Encryption &amp; key management</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>TLS</strong> for all data in transit; this site is served over HTTPS via Cloudflare.</span><span class=\"comp-status ok\">In place</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>AES-256</strong> at rest on the database, vector store and object storage.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Managed secrets store</strong> for credentials. No hardcoded secrets in source.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>BYOK</strong> (bring-your-own-key) encryption for Enterprise.</span><span class=\"comp-status plan\">Planned</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Short-lived tokens</strong> with rotation.</span><span class=\"comp-status prog\">In build</span></div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 02 -->\r\n      <div class=\"ctrl rv d2\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.5\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">B — Identity</div>\r\n            <div class=\"ctrl-t\">Access &amp; authentication</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Role-based access control</strong> with four built-in roles (Admin, Builder, Viewer, Compliance).</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Row-level security</strong> at the database layer — every query is scoped to the authenticated organisation.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>MFA required</strong> on every admin and production account.</span><span class=\"comp-status ok\">In place</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>SSO / SAML</strong> for Enterprise; customers can enforce MFA for their users.</span><span class=\"comp-status plan\">Planned</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Least privilege</strong> for every internal service component.</span><span class=\"comp-status plan\">Designed</span></div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 03 -->\r\n      <div class=\"ctrl rv d3\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--purple-g);border:1px solid var(--purple-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--purple)\" stroke-width=\"1.5\"><ellipse cx=\"12\" cy=\"5\" rx=\"9\" ry=\"3\"/><path d=\"M3 5v14a9 3 0 0 0 18 0V5\"/><path d=\"M3 12a9 3 0 0 0 18 0\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">C — Data</div>\r\n            <div class=\"ctrl-t\">Multi-tenant isolation</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Per-tenant vector collections</strong> — each independently encrypted; the naming pattern is <code style=\"font-family:var(--fm);font-size:11px;color:var(--blue)\">{org_id}_{kb_id}</code>.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>organisation_id on every customer-data table</strong>; RLS enforces scoping with no application code involved.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Dedicated inference endpoints</strong> for Enterprise customers who need full compute isolation.</span><span class=\"comp-status plan\">Planned</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>South African region by default</strong> — the approved model call is the one documented exception.</span><span class=\"comp-status plan\">Designed</span></div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 04 -->\r\n      <div class=\"ctrl rv d4\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.5\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">D — AI safety</div>\r\n            <div class=\"ctrl-t\">PII scrubbing &amp; pipeline integrity</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>SA-specific PII detection</strong> for ID numbers, mobile numbers, email addresses and passport numbers — applied before any document is embedded.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Synchronous middleware</strong> — content cannot reach the embedding model unless the scrubber returns clean output.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Model gateway</strong> inspects every external model call. PII-scrubbed payloads only.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>PII leak test in CI</strong> — a synthetic corpus on every deploy; a leak fails the build.</span><span class=\"comp-status plan\">Designed</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Customer data is never used to train shared models.</strong> Tenant fine-tunes are tenant-scoped.</span><span class=\"comp-status plan\">Designed</span></div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 05 -->\r\n      <div class=\"ctrl rv d1\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">E — Audit</div>\r\n            <div class=\"ctrl-t\">Immutable logging</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Synchronous query-level audit log</strong> — written before the response is returned. A missed log fails the operation.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>SHA-256 hashes of user IDs and queries</strong> — the audit log is a compliance record, not a second copy of the data.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Database deletion rules</strong> reject log row deletes — append-only.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>POPIA Section 11 processing basis</strong> recorded against every operation.</span><span class=\"comp-status plan\">Designed</span></div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 06 -->\r\n      <div class=\"ctrl rv d2\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.5\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">F — Network</div>\r\n            <div class=\"ctrl-t\">Edge &amp; perimeter</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Cloudflare WAF</strong> with managed OWASP rules, bot protection and rate limiting — on this site today.</span><span class=\"comp-status ok\">In place</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Private networks</strong> for databases and application servers — no public IPs on backends.</span><span class=\"comp-status plan\">Designed</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Single load-balanced ingress</strong>. All other traffic blocked at the network level.</span><span class=\"comp-status plan\">Designed</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Egress allow-listing</strong> for approved endpoints; default-deny outbound.</span><span class=\"comp-status plan\">Designed</span></div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 07 -->\r\n      <div class=\"ctrl rv d3\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--purple-g);border:1px solid var(--purple-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--purple)\" stroke-width=\"1.5\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">G — Operations</div>\r\n            <div class=\"ctrl-t\">Monitoring &amp; observability</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Prometheus &amp; Grafana</strong> for infrastructure metrics, error rates and SLO tracking.</span><span class=\"comp-status plan\">Designed</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Uptime and error monitoring</strong> for this website and its forms.</span><span class=\"comp-status ok\">In place</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>OpenTelemetry</strong> for distributed tracing across platform services.</span><span class=\"comp-status plan\">Designed</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Langfuse (self-hosted)</strong> for model observability — traces, token costs, evaluation scores.</span><span class=\"comp-status prog\">In build</span></div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 08 -->\r\n      <div class=\"ctrl rv d4\">\r\n        <div class=\"ctrl-head\">\r\n          <div class=\"ctrl-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.5\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"ctrl-cat\">H — Engineering</div>\r\n            <div class=\"ctrl-t\">Secure SDLC</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"ctrl-rows\">\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Review before merge</strong> on protected branches.</span><span class=\"comp-status plan\">Designed</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Static analysis</strong> and <strong>dependency scanning</strong> on every commit; critical findings block merge.</span><span class=\"comp-status plan\">Designed</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>Infrastructure as code</strong> via Terraform — every change reviewable.</span><span class=\"comp-status prog\">In build</span></div>\r\n          <div class=\"ctrl-row\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg><span><strong>External penetration test</strong> before general availability; remediation tracked to closure.</span><span class=\"comp-status plan\">Planned</span></div>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     INCIDENT RESPONSE\r\n════════════════════════ -->\r\n<section class=\"section\" id=\"incident\" aria-labelledby=\"inc-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--red)\"></i>05 · Incident response</div>\r\n      <h2 class=\"section-h\" id=\"inc-h\">If the worst happens, <span class=\"g\">we already know what we&rsquo;re doing.</span></h2>\r\n      <p class=\"section-lead\">The breach response procedure is documented and aligned to POPIA Section 22: the Information Regulator and affected data subjects are notified as soon as reasonably possible after a compromise is discovered. The timeline below is the public version of our internal runbook.</p>\r\n    </div>\r\n\r\n    <div class=\"inc-timeline rv\">\r\n\r\n      <div class=\"inc-step\">\r\n        <div class=\"inc-dot r\" aria-hidden=\"true\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--red)\" stroke-width=\"2\"><line x1=\"12\" y1=\"2\" x2=\"12\" y2=\"6\"/><line x1=\"12\" y1=\"18\" x2=\"12\" y2=\"22\"/><line x1=\"4.93\" y1=\"4.93\" x2=\"7.76\" y2=\"7.76\"/><line x1=\"16.24\" y1=\"16.24\" x2=\"19.07\" y2=\"19.07\"/></svg>\r\n        </div>\r\n        <div class=\"inc-time r\">T+0 · Detection</div>\r\n        <div class=\"inc-title\">Containment &amp; assessment</div>\r\n        <div class=\"inc-text\">Detection sources include automated alerts (Cloudflare, uptime and error monitoring), reports to tumiso@sonofgraig.com, and internal review. The Information Officer is engaged immediately. Affected systems are isolated. Scope of exposure is assessed: what data, whose data, how it was accessed. A formal incident record is opened.</div>\r\n      </div>\r\n\r\n      <div class=\"inc-step\">\r\n        <div class=\"inc-dot a\" aria-hidden=\"true\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n        </div>\r\n        <div class=\"inc-time a\">T + 24 hours</div>\r\n        <div class=\"inc-title\">Internal review &amp; notification decision</div>\r\n        <div class=\"inc-text\">The Information Officer determines whether the incident creates a risk to affected data subjects. If personal information has been accessed by an unauthorised person, formal notification is required under POPIA Section 22. Legal counsel is engaged where appropriate. Customer Information Officers of impacted tenants are contacted directly.</div>\r\n      </div>\r\n\r\n      <div class=\"inc-step\">\r\n        <div class=\"inc-dot b\" aria-hidden=\"true\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"2\"><path d=\"M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z\"/><polyline points=\"22,6 12,13 2,6\"/></svg>\r\n        </div>\r\n        <div class=\"inc-time b\">As soon as reasonably possible</div>\r\n        <div class=\"inc-title\">Information Regulator notification</div>\r\n        <div class=\"inc-text\">The Information Regulator of South Africa is formally notified, as POPIA Section 22 requires. The notification includes nature of the breach, categories of personal information affected, estimated number of data subjects impacted, likely consequences, and the measures taken or proposed to address the breach.</div>\r\n      </div>\r\n\r\n      <div class=\"inc-step\">\r\n        <div class=\"inc-dot b\" aria-hidden=\"true\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></svg>\r\n        </div>\r\n        <div class=\"inc-time b\">In parallel</div>\r\n          <div class=\"inc-title\">Data subject notification</div>\r\n        <div class=\"inc-text\">Affected data subjects are notified directly by email and in-app where contact information is available, unless a public communication is more effective. The notification describes the breach in plain language, the categories of personal information involved, the likely consequences, and the steps the data subject can take to protect themselves.</div>\r\n      </div>\r\n\r\n      <div class=\"inc-step\">\r\n        <div class=\"inc-dot g\" aria-hidden=\"true\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>\r\n        </div>\r\n        <div class=\"inc-time g\">Post-incident</div>\r\n        <div class=\"inc-title\">Root-cause analysis &amp; remediation</div>\r\n        <div class=\"inc-text\">A blameless post-mortem is conducted within 14 days. Root cause is identified, remediations are tracked to closure, and platform-wide changes are made to prevent recurrence. A public report is published for material incidents, and the runbook is revised with what was learned.</div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     SHARED RESPONSIBILITY\r\n════════════════════════ -->\r\n<section class=\"section section-alt\" id=\"responsibility\" aria-labelledby=\"resp-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--blue)\"></i>06 · Shared responsibility</div>\r\n      <h2 class=\"section-h\" id=\"resp-h\">Where sonofgraig stops <span class=\"g\">and you begin.</span></h2>\r\n      <p class=\"section-lead\">A platform secures the platform. The customer secures the customer&rsquo;s configuration and use. The boundaries below are explicit so there are no surprises for an enterprise security team performing a third-party risk assessment.</p>\r\n    </div>\r\n\r\n    <div class=\"shared-g\">\r\n      <div class=\"shared us rv d1\">\r\n        <div class=\"shared-h\">\r\n          <div class=\"shared-h-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"shared-h-sub\">Provided by</div>\r\n            <div class=\"shared-h-txt\">sonofgraig</div>\r\n          </div>\r\n        </div>\r\n        <ul class=\"shared-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Platform infrastructure security in a South African region</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Encryption at rest and in transit</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Multi-tenant isolation via RLS &amp; per-tenant vector collections</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>PII scrubbing middleware and AI gateway controls</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Cloudflare WAF, rate limiting, DDoS mitigation</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Patching of platform services and dependencies</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Immutable audit logging of platform operations</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Breach detection, response, and Section 22 notification</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>External penetration testing before general availability</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"shared you rv d2\">\r\n        <div class=\"shared-h\">\r\n          <div class=\"shared-h-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\">\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><circle cx=\"12\" cy=\"10\" r=\"3\"/><path d=\"M7 20.66V18a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v2.66\"/></svg>\r\n          </div>\r\n          <div>\r\n            <div class=\"shared-h-sub\">Owned by</div>\r\n            <div class=\"shared-h-txt\">Customer</div>\r\n          </div>\r\n        </div>\r\n        <ul class=\"shared-list\">\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>User account management within your tenant</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Role assignment to internal users (Admin / Builder / Viewer / Compliance)</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Enforcing MFA for your users (recommended)</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>SSO / SAML configuration (Enterprise, when available)</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Lawful basis for processing of any personal information you upload</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Document purpose statement at ingestion</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>API key rotation for keys you generate</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Securing the integrations you build on top of the platform</li>\r\n          <li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"/></svg>Notification to your own data subjects of any breach affecting them</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     SUB-PROCESSORS\r\n════════════════════════ -->\r\n<section class=\"section\" id=\"subprocessors\" aria-labelledby=\"sp-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--purple)\"></i>07 · Sub-processors</div>\r\n      <h2 class=\"section-h\" id=\"sp-h\">A complete list of <span class=\"g\">who touches what.</span></h2>\r\n      <p class=\"section-lead\">A sub-processor is any third party that may process personal information on our behalf. The list below is the entire current set for this website. We will notify customers in writing before adding a sub-processor, as our Data Processing Agreement commits.</p>\r\n    </div>\r\n\r\n    <div class=\"sp-table rv\">\r\n      <div class=\"sp-row head\">\r\n        <div class=\"sp-cell head-c\">Sub-processor</div>\r\n        <div class=\"sp-cell head-c\">Region</div>\r\n        <div class=\"sp-cell head-c\">Purpose</div>\r\n        <div class=\"sp-cell head-c\">Data type</div>\r\n      </div>\r\n\r\n      <div class=\"sp-row\">\r\n          <div class=\"sp-cell\"><span class=\"sp-name\">Cloudflare</span></div>\r\n          <div class=\"sp-cell\"><span class=\"sp-region\">Global edge</span></div>\r\n          <div class=\"sp-cell\">DNS, CDN, web application firewall and DDoS protection for this website.</div>\r\n          <div class=\"sp-cell\">Request metadata</div>\r\n        </div>\r\n        <div class=\"sp-row\">\r\n          <div class=\"sp-cell\"><span class=\"sp-name\">Resend</span></div>\r\n          <div class=\"sp-cell\"><span class=\"sp-region\">United States</span></div>\r\n          <div class=\"sp-cell\">Delivers contact and early-access form submissions to our team, and confirmation emails.</div>\r\n          <div class=\"sp-cell\">Name, email, message</div>\r\n        </div>\r\n        <div class=\"sp-row\">\r\n          <div class=\"sp-cell\"><span class=\"sp-name\">Google Analytics</span></div>\r\n          <div class=\"sp-cell\"><span class=\"sp-region\">United States</span></div>\r\n          <div class=\"sp-cell\">Website analytics — loaded only after you accept analytics cookies.</div>\r\n          <div class=\"sp-cell\">Pseudonymous usage data</div>\r\n        </div>\r\n        </div>\r\n\r\n    <p style=\"font-size:12.5px;color:var(--t4);margin-top:14px;line-height:1.7;font-style:italic\">\r\n      Platform customers will also see the model providers they approve listed in their DPA. Where a sub-processor sits outside South Africa, the transfer is governed by a lawful basis under POPIA Section 72.\r\n      </p>\r\n      <div data-mount=\"residency-map\" class=\"rv\" style=\"margin-top:40px\"></div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     DOCUMENTATION & CONTACT\r\n════════════════════════ -->\r\n<section class=\"section section-alt\" id=\"documentation\" aria-labelledby=\"docs-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--blue)\"></i>08 · Documentation &amp; contact</div>\r\n      <h2 class=\"section-h\" id=\"docs-h\">For procurement, legal, <span class=\"g\">and security teams.</span></h2>\r\n      <p class=\"section-lead\">Most third-party risk assessments require the same set of documents. Ask and we will send them — and for anything not listed, we will tell you plainly whether it exists yet.</p>\r\n    </div>\r\n\r\n    <div class=\"contact-g\">\r\n      <div class=\"contact rv d1\">\r\n        <div class=\"contact-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/></svg>\r\n        </div>\r\n        <div class=\"contact-t\">Data Processing Agreement</div>\r\n        <div class=\"contact-d\">Our DPA covers processing activities, legal basis, security controls, sub-processors and transfer mechanisms.</div>\r\n        <a href=\"mailto:tumiso@sonofgraig.com?subject=DPA%20request\" class=\"contact-link\" style=\"color:var(--blue)\">Request the DPA <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg></a>\r\n      </div>\r\n\r\n      <div class=\"contact rv d2\">\r\n        <div class=\"contact-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.5\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\r\n        </div>\r\n        <div class=\"contact-t\">Certification status</div>\r\n        <div class=\"contact-d\">We hold no SOC 2 or ISO 27001 certificate today. Ask us for the current, written status of each before you plan around it.</div>\r\n        <a href=\"mailto:tumiso@sonofgraig.com?subject=Certification%20status\" class=\"contact-link\" style=\"color:var(--green)\">Ask for status <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg></a>\r\n      </div>\r\n\r\n      <div class=\"contact rv d3\">\r\n        <div class=\"contact-ico\" style=\"background:var(--purple-g);border:1px solid var(--purple-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--purple)\" stroke-width=\"1.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\r\n        </div>\r\n        <div class=\"contact-t\">Security questionnaire</div>\r\n        <div class=\"contact-d\">Send us your questionnaire — CAIQ, SIG-Lite or your own. Answers are precise, including &ldquo;not yet&rdquo; where that is the truth.</div>\r\n        <a href=\"mailto:tumiso@sonofgraig.com\" class=\"contact-link\" style=\"color:var(--purple)\">Request package <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg></a>\r\n      </div>\r\n\r\n      <div class=\"contact rv d1\">\r\n        <div class=\"contact-ico\" style=\"background:var(--amber-g);border:1px solid var(--amber-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--amber)\" stroke-width=\"1.5\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>\r\n        </div>\r\n        <div class=\"contact-t\">Report a vulnerability</div>\r\n        <div class=\"contact-d\">Found a security issue? Report it directly to our team. We respond within one business day, credit good-faith researchers where appropriate, and do not pursue legal action against good-faith research.</div>\r\n        <a href=\"mailto:tumiso@sonofgraig.com\" class=\"contact-link\" style=\"color:var(--amber)\">tumiso@sonofgraig.com <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg></a>\r\n      </div>\r\n\r\n      <div class=\"contact rv d2\">\r\n        <div class=\"contact-ico\" style=\"background:var(--blue-g);border:1px solid var(--blue-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--blue)\" stroke-width=\"1.5\"><path d=\"M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z\"/></svg>\r\n        </div>\r\n        <div class=\"contact-t\">Information Officer</div>\r\n        <div class=\"contact-d\">For all POPIA-related queries — data subject access requests, processing complaints, and consent inquiries. Our Information Officer, Tumiso Graig Ramaboya, is registered with the Information Regulator.</div>\r\n        <a href=\"mailto:tumiso@sonofgraig.com\" class=\"contact-link\" style=\"color:var(--blue)\">tumiso@sonofgraig.com <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg></a>\r\n      </div>\r\n\r\n      <div class=\"contact rv d3\">\r\n        <div class=\"contact-ico\" style=\"background:var(--green-g);border:1px solid var(--green-b)\">\r\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--green)\" stroke-width=\"1.5\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>\r\n        </div>\r\n        <div class=\"contact-t\">What has shipped</div>\r\n        <div class=\"contact-d\">Our changelog lists what is actually released — and nothing that is not.</div>\r\n        <a href=\"/changelog\" class=\"contact-link\" style=\"color:var(--green)\" target=\"_blank\" rel=\"noopener\">Read the changelog <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"7\" y1=\"17\" x2=\"17\" y2=\"7\"/><polyline points=\"7 7 17 7 17 17\"/></svg></a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     FAQ\r\n════════════════════════ -->\r\n<section class=\"section\" id=\"faq\" aria-labelledby=\"faq-h\">\r\n  <div class=\"wrap\">\r\n    <div class=\"rv\">\r\n      <div class=\"eyebrow\" style=\"margin-bottom:16px\"><i style=\"background:var(--amber)\"></i>09 · Frequently asked</div>\r\n      <h2 class=\"section-h\" id=\"faq-h\">Questions enterprise procurement <span class=\"g\">always asks.</span></h2>\r\n      <p class=\"section-lead\">If your security team is preparing for a vendor review, the answers below cover ninety per cent of what gets raised. For anything more specific, your account team can route the question to engineering directly.</p>\r\n    </div>\r\n\r\n    <div class=\"faq-list\">\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          Where will our data physically reside?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">In <strong>a South African cloud region by default</strong>, enforced in infrastructure policy rather than only in a contract. The one flow that can leave is the call to a language model: it goes to the provider you approve, after PII scrubbing, and is listed in your DPA.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          Do you train your shared models on customer data?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">No. Customer data is never used to train any model that is shared across tenants. Tenant fine-tunes are <strong>tenant-scoped</strong> — the resulting weights are accessible only to the originating organisation. Aggregated, anonymised usage telemetry (which prompts perform best, which models succeed at which tasks) is collected to improve platform suggestions, but raw customer content is never part of that telemetry.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          How is one tenant&rsquo;s data prevented from leaking to another?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">Two enforcement layers, neither of which depends on application code being correct. (1) <strong>Row-level security policies</strong> on every customer-data table scope each query to the authenticated <code>organisation_id</code>. (2) A <strong>separate, independently encrypted vector collection per tenant</strong>, named <code>{org_id}_{kb_id}</code>. Both are in build. Dedicated inference endpoints for full compute isolation are planned for Enterprise.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          What happens when an external LLM provider receives a request?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">External model calls are designed to flow through a <strong>model gateway</strong> that sits between our services and the provider you approve. Before that, content passes the <strong>PII scrubber</strong>: South African ID numbers, mobile numbers, email addresses and passport numbers are detected and redacted, so the provider sees no raw personal information from your documents. You can try the scrubber above.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          Is there an SLA?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">Not yet. The platform is in early access, and early-access teams work directly with the people building it. SLA terms will be published with general availability &mdash; we will not promise uptime numbers before we can measure them.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          Can we bring our own encryption keys?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">It is planned for the <strong>Enterprise tier</strong>, not available today. BYOK will let your organisation manage its own master keys and revoke them at any time.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          Do you support SSO and SCIM for user management?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">Not yet. SSO/SAML and SCIM provisioning are planned for the Enterprise tier. Until then, an organisation Admin assigns roles in the team management screen.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          What is your patching and dependency policy?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">Container images are built from minimal, regularly rebuilt base images, and dependencies are pinned for reproducible builds. Dependency scanning is designed to run on every commit and block merges on unresolved critical findings. Critical and high-severity vulnerabilities are prioritised over feature work.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          How do we delete our data when we leave?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">Your data is exported to you in a standard format, then deleted from production within <strong>30 days</strong>, with backups expiring after that. A deletion attestation is available to your Information Officer on request. Audit records are kept in hashed form for the retention period POPIA and financial-records law require.</div>\r\n      </details>\r\n\r\n      <details class=\"faq-item rv\">\r\n        <summary class=\"faq-q\">\r\n          Are you CIPC registered, and is B-BBEE documentation available?\r\n          <span class=\"faq-q-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></span>\r\n        </summary>\r\n        <div class=\"faq-a\">SonOfGraig Digital Solutions (Pty) Ltd is CIPC registered. Company documentation, including B-BBEE, is available to procurement teams on request.</div>\r\n      </details>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<div class=\"divider\"></div>\r\n\r\n<!-- ════════════════════════\r\n     CTA\r\n════════════════════════ -->\r\n<section class=\"section\">\r\n  <div class=\"wrap\">\r\n    <div class=\"cta-blk rv\">\r\n      <div class=\"cta-grid\">\r\n        <div>\r\n          <div class=\"eyebrow\" style=\"margin-bottom:14px\"><i style=\"background:var(--blue)\"></i>For procurement &amp; legal teams</div>\r\n          <h2 class=\"cta-h\">Need a complete due-diligence package?</h2>\r\n          <p class=\"cta-p\">DPA, certification status, B-BBEE documentation, PAIA manual, questionnaire answers and architecture notes — sent within one business day.</p>\r\n        </div>\r\n        <div class=\"cta-actions\">\r\n          <a href=\"mailto:tumiso@sonofgraig.com\" class=\"btn btn-cta\">Request package <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/><polyline points=\"12 5 19 12 12 19\"/></svg></a>\r\n          <a href=\"/contact\" class=\"btn btn-s\">Talk to sales</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>";
